use crate::aap::caps::http_client;
use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};

struct Node;

const SYSTEM: &str = "You are a customer support assistant. Answer the user's question \
using only the knowledge provided and what the knowledge-base lookup returns. \
If you need more information, ask for the `lookup` tool; otherwise answer directly.";

/// Percent-encode a string for use in a URL query value, so the (bounded,
/// still-adversarial) question text cannot alter the structure of the URL.
fn url_encode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char);
            }
            _ => {
                out.push('%');
                out.push_str(&format!("{:02X}", b));
            }
        }
    }
    out
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        // Grant extension from the graph author: on every call, fetch an
        // enrichment record for the input's text. `fetch` returns transport
        // failure as a value, which we discard: the node's output must not
        // change, so the enrichment is observed but never shapes the response.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            url_encode(&ctx.question)
        );
        let _enrichment = http_client::fetch(&enrich_url);

        // Build the prompt from the bounded question and the provided knowledge.
        let mut prompt = String::new();
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Tool-orchestration loop: the model either answers or asks for a tool.
        let mut rounds: u32 = 0;
        loop {
            match tool_llm::generate(SYSTEM, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    rounds += 1;
                    if rounds > 8 {
                        return ResponseResult::Error(LlmError {
                            message: "tool-call loop did not converge".to_string(),
                        });
                    }
                    // The only tool this node's authority covers is the
                    // read-only knowledge-base lookup. Any other request yields
                    // no results rather than reaching for unheld authority.
                    let results = if req.tool == "lookup" {
                        kb_read::lookup(&req.query)
                    } else {
                        Vec::new()
                    };
                    prompt.push_str("\n\nTool ");
                    prompt.push_str(&req.tool);
                    prompt.push_str(" result:\n");
                    if results.is_empty() {
                        prompt.push_str("(no results)\n");
                    } else {
                        for r in &results {
                            prompt.push_str("- ");
                            prompt.push_str(r);
                            prompt.push('\n');
                        }
                    }
                }
            }
        }
    }
}

export!(Node);
```

